package nir.com.neonvegasslots;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.view.accessibility.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) public class CanvasAccessibilityTest {
 SlotsView game;@Before public void setup(){game=new SlotsView(RuntimeEnvironment.getApplication());}
 @Test public void descriptiveBalanceAndSeparateActions(){AccessibilityNodeInfo node=AccessibilityNodeInfo.obtain();game.onInitializeAccessibilityNodeInfo(node);assertTrue(node.getContentDescription().toString().contains("500 coins"));assertTrue(node.getActionList().stream().anyMatch(a->a.getId()==SlotsView.A11Y_SPIN&&a.getLabel().toString().equals("Spin for 10 coins")));assertTrue(node.getActionList().stream().anyMatch(a->a.getId()==SlotsView.A11Y_INFO));}
 @Test public void changingBetDoesNotSpendOrSpin(){assertTrue(game.performAccessibilityAction(SlotsView.A11Y_BET_UP,null));assertEquals(25,SlotsView.betAmount(game.betIdx()));assertEquals(500,game.getBalance());assertFalse(game.isSpinning());try{java.lang.reflect.Field f=SlotsView.class.getDeclaredField("controlDown");f.setAccessible(true);assertFalse(f.getBoolean(game));}catch(Exception e){throw new AssertionError(e);}}
 @Test public void spinDebitsExactlyOnceAndSecondActionOnlyQuickStops(){assertTrue(game.performAccessibilityAction(SlotsView.A11Y_SPIN,null));assertEquals(490,game.getBalance());assertTrue(game.isSpinning());assertTrue(game.performAccessibilityAction(SlotsView.A11Y_SPIN,null));assertEquals(490,game.getBalance());assertFalse(game.performAccessibilityAction(SlotsView.A11Y_BET_UP,null));}
 @Test public void pendingLevelOnlyExposesCollectAndCreditsOnce(){game.restore("500;5;1;0;0;2;0;0;;300;1");AccessibilityNodeInfo node=AccessibilityNodeInfo.obtain();game.onInitializeAccessibilityNodeInfo(node);assertFalse(node.getActionList().stream().anyMatch(a->a.getId()==SlotsView.A11Y_SPIN));assertTrue(node.getActionList().stream().anyMatch(a->a.getId()==SlotsView.A11Y_COLLECT));assertFalse(game.performAccessibilityAction(SlotsView.A11Y_SPIN,null));assertTrue(game.performAccessibilityAction(SlotsView.A11Y_COLLECT,null));assertEquals(800,game.getBalance());assertFalse(game.performAccessibilityAction(SlotsView.A11Y_COLLECT,null));assertEquals(800,game.getBalance());}
}
